using System;
using System.Collections.Generic;
using System.Globalization;

namespace DaoDenLong.Core
{
    /// <summary>
    /// v1.3 (TICKET-04) — the soak test's random player input, generated by the seeded core RNG.
    /// Every 30 ticks a new move direction is chosen and held until the next re-roll (9 choices:
    /// 8 compass directions plus standing still); every tick each button fires with its own
    /// probability (jump 5 %, dash 3 %, pulse 2 %, interact 10 %). The draw order per tick is
    /// pinned: direction (only on a 30-tick boundary), jump, dash, pulse, interact — so two runs
    /// of the same seed feed the identical stream.
    /// </summary>
    public static class SoakInputs
    {
        public static List<InputFrame> Generate(long seed, long ticks)
        {
            Rng rng = new Rng(seed == 0 ? 0x9E3779B97F4A7C15UL : (ulong)seed);
            List<InputFrame> frames = new List<InputFrame>((int)ticks);
            double mx = 0.0, mz = 0.0;

            for (long k = 0; k < ticks; k++)
            {
                if (k % 30 == 0)
                {
                    int dir = rng.Next(9);                      // 0 = stand, 1..8 = the compass
                    if (dir > 0)
                    {
                        double a = (dir - 1) * Math.PI / 4.0;
                        mx = Math.Sin(a); mz = Math.Cos(a);
                    }
                    else { mx = 0.0; mz = 0.0; }
                }

                InputFrame f = new InputFrame { Tick = k, MoveX = mx, MoveZ = mz };
                f.Jump = rng.NextDouble() < 0.05;
                f.Dash = rng.NextDouble() < 0.03;
                f.Pulse = rng.NextDouble() < 0.02;
                f.Interact = rng.NextDouble() < 0.10;
                frames.Add(f);
            }
            return frames;
        }

        /// <summary>Night length in ticks for the standard Night durations (v1.2: 240/270/300 s).</summary>
        public static long NightTicks(int night)
        {
            Tuning t = Tuning.Standard();
            int s = night == 1 ? t.Night1DurationS : (night == 2 ? t.Night2DurationS : t.Night3DurationS);
            return (long)s * Simulation.TicksPerSecond;
        }
    }
}
